import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Filter to significant features (p < 0.05) and remove near-duplicates
    sig_ids = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            try:
                t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
                if abs(t_stat) > 2.0:
                    sig_ids.append(fid)
            except:
                continue

    # Remove near-duplicates based on correlation
    keep = []
    seen = set()
    for fid in sig_ids:
        if fid in seen:
            continue
        keep.append(fid)
        # Find correlated features (|r| >= 0.6) and mark them as seen
        col_idx = feats.column(fid)
        for fid2 in sig_ids:
            if fid2 == fid or fid2 in seen:
                continue
            try:
                corr = np.corrcoef(feats.x[:, col_idx], feats.x[:, feats.column(fid2)])[0,1]
                if abs(corr) >= 0.6:
                    seen.add(fid2)
            except:
                continue

    # If no significant features, return empty design
    if not keep:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Try to find a mechanism using logistic regression
    try:
        X = feats.x[:, [feats.column(fid) for fid in keep]]
        y = feats.y

        # Use mutual information to rank features
        mi_scores = mutual_info_classif(X, y)
        ranked_indices = np.argsort(mi_scores)[::-1]

        # Select top features for regression
        selected_features = [keep[i] for i in ranked_indices[:min(10, len(keep))]]

        # Try simple logistic regression with selected features
        X_selected = feats.x[:, [feats.column(fid) for fid in selected_features]]
        lr = LogisticRegression(penalty='l1', solver='liblinear', random_state=42)
        lr.fit(X_selected, y)

        # Get coefficients
        coef = lr.coef_[0]

        # Select features with non-zero coefficients
        significant_features = [selected_features[i] for i, c in enumerate(coef) if abs(c) > 1e-5]

        # If we have no significant features, return empty design
        if not significant_features:
            return Design(drivers=(), columns=(), products=(), loadings={})

        # For simplicity, use the most significant feature as driver if it's strong enough
        drivers = []
        if len(significant_features) > 0:
            # Check if any feature shows strong effect (t-test > 2.5)
            for fid in significant_features:
                try:
                    col_idx = feats.column(fid)
                    t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, col_idx], feats.x[feats.y==0, col_idx])
                    if abs(t_stat) > 2.5:
                        drivers.append(fid)
                        break
                except:
                    continue

        # Return final design
        return Design(
            drivers=tuple(drivers[:MAX_DRIVERS]),
            columns=tuple(selected_features),
            products=(),
            loadings={}
        )
    except:
        # Fallback to empty design if anything fails
        return Design(drivers=(), columns=(), products=(), loadings={})

